420	    /// Run `f` with a [`SerializationContext`] over the **default** converter.
421	    ///
422	    /// Every codec test must go through this rather than calling
423	    /// `Wrapper::from_payloads` directly: a direct call exercises none of the
424	    /// `Composite` -> `UseWrappers` dispatch the design depends on. This crate
425	    /// never configures a `DataConverter` itself — the caller supplies the
426	    /// connected `temporalio_client::Client` (`TemporalAgentWorkerBuilder::client`)
427	    /// — so a worker built against a client left on the SDK's defaults yields
428	    /// exactly `PayloadConverter::default()`. That is the configuration these
429	    /// tests target; a caller-supplied client with a non-default
430	    /// `DataConverter` is out of scope here, same as it always was for the
431	    /// legacy `MultiArgs{N}` shapes this design builds on.
432	    fn with_ctx<R>(f: impl FnOnce(&SerializationContext<'_>) -> R) -> R {
433	        let converter = PayloadConverter::default();
434	        let data = SerializationContextData::Activity;
435	        let ctx = SerializationContext {
436	            data: &data,
437	            converter: &converter,
438	        };
439	        f(&ctx)
440	    }
