622	                .from_payloads::<RenderInstructionsInput>(ctx, vec![payload])
623	                .expect_err("a bare string is not an envelope");
624	
625	            assert!(
626	                matches!(err, PayloadConversionError::EncodingError(_)),
627	                "expected EncodingError from the envelope arm, got {err:?}"
628	            );
629	
630	            let display = err.to_string();
